          "artifact_ref": "prometheus://metric?query=sum(rate(http_requests_total%7Bjob%3D%22payment-svc%22%2Cstatus%3D~%225..%22%2Cpath%3D%22%2Fv1%2Fcharge%22%7D%5B5m%5D))%20by%20(error)&time=2026-09-05T08:55:00Z"
